const body = $json.body || {};
const action = String(body.action || '').trim().toLowerCase();
const allowed = new Set(['pause','resume','retry_failed','update_rules']);
if (!allowed.has(action)) {
  return [{ json: { ok: false, error: 'unsupported_action', action } }];
}

let response = { ok: true, action, timestamp: new Date().toISOString() };

if (action === 'pause') {
  response.state = 'paused';
  response.note = 'Use this response to toggle your dashboard kill switch and pause scheduler/workflow activation in n8n.';
}

if (action === 'resume') {
  response.state = 'running';
  response.note = 'Resume scheduler/workflow activation from n8n UI or API.';
}

if (action === 'retry_failed') {
  response.filter = body.filter || { whatsapp_status: 'failed', dead_letter: false };
  response.note = 'Call your retry workflow path using this filter.';
}

if (action === 'update_rules') {
  response.rule_version = Number(body.rule_version || Date.now());
  response.note = 'Persist rules to sheet/config table and reload in processing workflows.';
}

return [{ json: response }];
